create table RB_CLIENT_RESTRAINTS (RES_SEQ_NO VARCHAR(50) not null  ,RESTRAINT_TYPE VARCHAR(3) null  ,SOURCE_TYPE VARCHAR(10) null  ,TRAN_DATE TIMESTAMP(3) null  ,TRAN_BRANCH VARCHAR(30) null  ,CLIENT_NO VARCHAR(22) not null  ,START_DATE TIMESTAMP(3) null  ,TERM VARCHAR(5) null  ,TERM_TYPE VARCHAR(1) null  ,END_DATE TIMESTAMP(3) null  ,RESTRAINTS_STATUS VARCHAR(1) null  ,NARRATIVE VARCHAR(600) null  ,USER_ID VARCHAR(30) null  ,AUTH_USER_ID VARCHAR(30) null  ,LAST_CHANGE_DATE TIMESTAMP(3) null  ,LAST_CHANGE_USER_ID VARCHAR(30) null  ,TRAN_TIMESTAMP VARCHAR(26) null  ,COMPANY VARCHAR(20) null  ,CREATE_TIMESTAMP VARCHAR(26) null  ,RES_PRIORITY VARCHAR(2) null  , primary key(RES_SEQ_NO,CLIENT_NO));